<script lang="ts">
  import {onMount} from 'svelte';import {EditorState} from '@codemirror/state';import {EditorView,keymap,lineNumbers,highlightActiveLine,highlightActiveLineGutter,drawSelection,dropCursor,rectangularSelection} from '@codemirror/view';import {defaultKeymap,history,historyKeymap} from '@codemirror/commands';import {syntaxHighlighting,HighlightStyle,bracketMatching,foldGutter,foldKeymap} from '@codemirror/language';import {search,searchKeymap,highlightSelectionMatches,openSearchPanel} from '@codemirror/search';import {tags} from '@lezer/highlight';import {javascript} from '@codemirror/lang-javascript';import {css} from '@codemirror/lang-css';import {json} from '@codemirror/lang-json';import {html} from '@codemirror/lang-html';import {markdown} from '@codemirror/lang-markdown';import {python} from '@codemirror/lang-python';import {api} from '../lib/api.js';import {atlasEvents} from '../lib/atlas-events.js';import {atlasBuffers} from '../lib/buffer-store.js';import {openEditors,type EditorChange} from '../lib/open-editors.js';import {lineDiff,type DiffLine} from '../lib/line-diff.js';import Save from '@lucide/svelte/icons/save';import History from '@lucide/svelte/icons/history';import LoadingState from './LoadingState.svelte';
  import {gitGutter} from '../lib/git/git-gutter.js';
