  const base64=(value:string)=>{const bytes=new TextEncoder().encode(value);let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary)};
  function language(file:string){const ext=file.toLowerCase().split('.').pop()??'';if(ext==='svelte')return html();if(['ts','tsx','js','jsx','mjs','cjs'].includes(ext))return javascript({typescript:['ts','tsx'].includes(ext),jsx:['tsx','jsx'].includes(ext)});if(['css','scss','sass','less'].includes(ext))return css();if(['json','jsonc'].includes(ext))return json();if(['html','htm'].includes(ext))return html();if(['md','markdown'].includes(ext))return markdown();if(ext==='py')return python();return []}
  function announce(){window.dispatchEvent(new CustomEvent('atlas:file-dirty',{detail:{panelId:params.panelId,path:resourcePath,bufferId:params.bufferId,dirty}}))}
