  async function persist(path=resourcePath,createOnly=false){if(!view||saving||!path)return;const eventId=`file.save:${params.contextId??'local'}:${params.panelId??params.bufferId??crypto.randomUUID()}`;atlasEvents.begin({id:eventId,type:'file.save',title:createOnly?'Create file':'Save file',contextId:params.contextId??'local',panelId:params.panelId});const submitted=view.state.doc.toString();saving=true;status=createOnly?'Creating…':'Saving…';try{const result=await api<any>('/api/files/content',{method:createOnly?'POST':'PUT',body:JSON.stringify({contextId:params.contextId??'local',path,contentBase64:base64(submitted),...(createOnly?{createOnly:true}:{expectedFingerprint:fingerprint})})});atlasEvents.resolve(eventId,{message:createOnly?'File created.':'File saved.'});if(disposed)return;fingerprint=result.fingerprint;resourcePath=path;if(params.bufferId)atlasBuffers.bindResource(params.bufferId,{contextId:params.contextId??'local',path,fingerprint});dirty=view.state.doc.toString()!==submitted;announcedDirty=dirty;status=dirty?'Modified after save':`Saved via ${result.route.kind}`;announce();window.dispatchEvent(new CustomEvent('atlas:buffer-saved',{detail:{bufferId:params.bufferId,panelId:params.panelId,contextId:params.contextId??'local',path,fingerprint}}));if(historyOpen)void loadVersions()}catch(error:any){const message=error.status===409?'File changed on Device or already exists.':error.message;atlasEvents.fail(eventId,{message});if(!disposed)status=message}finally{saving=false;if(saveQueued){saveQueued=false;if(dirty&&!disposed)save()}}}
