  function save(){if(!view)return;if(saving){saveQueued=true;return}if(resourcePath)void persist(resourcePath,!fingerprint);else requestSaveAs()}
  function saveAs(){requestSaveAs()}
  function openFind(replace=false){if(!view)return false;view.focus();openSearchPanel(view);if(replace)queueMicrotask(()=>{const field=host?.querySelector<HTMLInputElement>('.cm-search input[name=replace]');field?.focus();field?.select()});return true}
  function select(line:number,column=1,length=0){if(!view)return;const target=view.state.doc.line(Math.min(Math.max(1,line),view.state.doc.lines)),from=Math.min(target.to,target.from+Math.max(0,column-1)),to=Math.min(view.state.doc.length,from+Math.max(0,length));view.dispatch({selection:{anchor:from,head:to},effects:EditorView.scrollIntoView(from,{y:'center'})})}
  // A clean editor follows the file on disk: one minimal change keeps the cursor.
  function syncSaved(content:string,next:string){if(!view)return;const current=view.state.doc.toString();if(current!==content){let start=0;while(start<current.length&&start<content.length&&current[start]===content[start])start++;let end=0;while(end<current.length-start&&end<content.length-start&&current[current.length-1-end]===content[content.length-1-end])end++;syncing=true;try{view.dispatch({changes:{from:start,to:current.length-end,insert:content.slice(start,content.length-end)},userEvent:'atlas.sync'})}finally{syncing=false}}fingerprint=next;dirty=false;announcedDirty=false;status='Updated from disk';if(params.bufferId)atlasBuffers.bindResource(params.bufferId,{contextId:params.contextId??'local',path:resourcePath,fingerprint:next});announce()}
  function applyChanges(changes:EditorChange[]){if(!view||!changes.length)return;view.dispatch({changes,userEvent:'input.replace'});status='Modified by replace · unsaved'}
  async function loadVersions(){versionsMessage='Loading versions…';versionPreview=undefined;try{const value=await api<any>(`/api/files/versions?contextId=${encodeURIComponent(params.contextId??'local')}&path=${encodeURIComponent(resourcePath)}`);versions=value.versions??[];versionsMessage=versions.length?'':'No previous versions yet. Atlas keeps the last 3 versions of every file it saves.'}catch(error){versions=[];versionsMessage=(error as Error).message}}
  function toggleHistory(){historyOpen=!historyOpen;if(historyOpen)void loadVersions()}
  async function previewVersion(slot:number){versionPreview={slot,message:'Loading…'};try{const value=await api<any>(`/api/files/versions/content?contextId=${encodeURIComponent(params.contextId??'local')}&path=${encodeURIComponent(resourcePath)}&slot=${slot}`);if(versionPreview?.slot!==slot)return;if(value.binary){versionPreview={slot,message:'Binary content · no preview'};return}const diff=lineDiff(view?.state.doc.toString()??'',value.text);versionPreview={slot,text:value.text,diff,message:diff===undefined?'Too large to diff in the browser.':diff.length?'':'Identical to the editor.'}}catch(error){versionPreview={slot,message:(error as Error).message}}}
  async function restoreVersion(version:any){if(!view||restoring)return;if(dirty&&!window.confirm('Restoring replaces the file on disk and discards your unsaved edits in this editor. Continue?'))return;restoring=true;status='Restoring…';try{await api<any>('/api/files/versions/restore',{method:'POST',body:JSON.stringify({contextId:params.contextId??'local',path:resourcePath,versionFingerprint:version.fingerprint,expectedFingerprint:fingerprint})});const opened=await api<any>(`/api/files/content?contextId=${encodeURIComponent(params.contextId??'local')}&path=${encodeURIComponent(resourcePath)}`);if(typeof opened.text==='string')syncSaved(opened.text,opened.fingerprint);status=`Restored version ${version.slot} · the replaced content is now version 1`;window.dispatchEvent(new CustomEvent('atlas:buffer-saved',{detail:{bufferId:params.bufferId,panelId:params.panelId,contextId:params.contextId??'local',path:resourcePath,fingerprint}}));await loadVersions()}catch(error:any){status=error.status===409?'The file changed on disk; reopen it before restoring.':error.message}finally{restoring=false}}
  const formatBytes=(value:number)=>value<1024?`${value} B`:value<1024*1024?`${(value/1024).toFixed(1)} KB`:value<1024**3?`${(value/1024/1024).toFixed(1)} MB`:`${(value/1024**3).toFixed(1)} GB`;
  const formatTime=(value:string)=>{const date=new Date(value),seconds=Math.round((Date.now()-date.getTime())/1000);const relative=seconds<60?'just now':seconds<3600?`${Math.floor(seconds/60)} min ago`:seconds<86400?`${Math.floor(seconds/3600)} h ago`:`${Math.floor(seconds/86400)} d ago`;return `${relative} · ${date.toLocaleString()}`};
  function mountEditor(doc:string,line=1,label='File',column=1,length=0){const safeLine=Math.min(Math.max(1,line),doc.split(/\r?\n/).length),anchor=doc.split(/\r?\n/).slice(0,safeLine-1).reduce((total,current)=>total+current.length+1,0);view=new EditorView({parent:host,state:EditorState.create({doc,selection:{anchor},extensions:[language(resourcePath||label),syntaxHighlighting(atlasHighlight),lineNumbers(),gitGutter(params.contextId??'local',resourcePath),foldGutter(),history(),drawSelection(),dropCursor(),rectangularSelection(),highlightActiveLine(),highlightActiveLineGutter(),bracketMatching(),highlightSelectionMatches(),search({top:true}),keymap.of([{key:'Mod-s',run:()=>{save();return true}},{key:'Mod-Shift-s',run:()=>{saveAs();return true}},{key:'Mod-h',preventDefault:true,run:()=>openFind(true)},...searchKeymap,...defaultKeymap,...historyKeymap,...foldKeymap]),EditorView.contentAttributes.of({'aria-label':`Editor for ${label}`}),EditorView.updateListener.of(update=>{if(!update.docChanged)return;if(params.bufferId)atlasBuffers.update(params.bufferId,update.state.doc.toString(),!syncing);if(syncing)return;dirty=true;if(!status.startsWith('Modified'))status='Modified';if(!announcedDirty){announcedDirty=true;announce()}}),EditorView.theme({'&':{height:'100%'},'.cm-scroller':{overflow:'auto'},'.cm-content':{caretColor:'#f4f8fb'}}),searchTheme]})});view.focus();if(line>1||column>1||length>0)select(line,column,length)}
  onMount(()=>{let alive=true;disposed=false;const reveal=(event:Event)=>{const detail=(event as CustomEvent<{panelId?:string;line?:number;column?:number;length?:number}>).detail;if(detail.panelId!==params.panelId||!view||!detail.line)return;select(detail.line,detail.column,detail.length);view.focus()},saveBuffer=(event:Event)=>{const detail=(event as CustomEvent<{bufferId:string;path:string}>).detail;if(detail.bufferId===params.bufferId)void persist(detail.path,true)},isActive=()=>Boolean(host?.offsetParent),saveActive=()=>{if(isActive())save()},saveAsActive=()=>{if(isActive())saveAs()},captureSaveAs=(event:KeyboardEvent)=>{if((event.ctrlKey||event.metaKey)&&event.shiftKey&&event.key.toLowerCase()==='s'&&view?.hasFocus){event.preventDefault();event.stopPropagation();saveAs()}},
      // Ctrl-F / Ctrl-H anywhere in this visible panel (header, search fields)
