      captureFind=(event:KeyboardEvent)=>{const mod=event.ctrlKey||event.metaKey,key=event.key.toLowerCase();if(!mod||event.shiftKey||event.altKey||(key!=='f'&&key!=='h')||!view||!isActive()||!section?.contains(document.activeElement))return;if(view.hasFocus&&key==='f')return;event.preventDefault();event.stopPropagation();openFind(key==='h')};
    window.addEventListener('atlas:file-reveal',reveal);window.addEventListener('atlas:save-buffer-as',saveBuffer);window.addEventListener('atlas:save-active',saveActive);window.addEventListener('atlas:save-as-active',saveAsActive);window.addEventListener('keydown',captureSaveAs,true);window.addEventListener('keydown',captureFind,true);
    const unregister=openEditors.register({get contextId(){return params.contextId??'local'},get path(){return resourcePath},panelId:params.panelId,bufferId:params.bufferId,dirty:()=>dirty,content:()=>view?.state.doc.toString()??'',fingerprint:()=>fingerprint,applyChanges,syncSaved});
    void(async()=>{try{if(params.bufferId){const buffer=atlasBuffers.get(params.bufferId);if(!buffer){status='This unsaved buffer is no longer available.';return}resourcePath=buffer.resource?.path??buffer.proposedPath??'';fingerprint=buffer.resource?.fingerprint??'';dirty=buffer.dirty;status=resourcePath&&!fingerprint?'Unsaved · first save creates exclusively':'Unsaved buffer';mountEditor(buffer.content,1,buffer.name);if(dirty){announcedDirty=true;announce()}return}const opened=await api<any>(`/api/files/content?contextId=${encodeURIComponent(params.contextId??'local')}&path=${encodeURIComponent(resourcePath)}`);if(!alive)return;if(opened.binary||opened.tooLarge||typeof opened.text!=='string'||!opened.fingerprint){status=opened.binary?`Binary file · ${formatBytes(opened.bytes)} · read-only`:opened.tooLarge?`${resourcePath.split('/').at(-1)||resourcePath} is ${formatBytes(opened.bytes)}; the editor opens files up to ${formatBytes(opened.limitBytes??2*1024*1024)}.`:'File cannot be edited.';return}fingerprint=opened.fingerprint;status=`${opened.bytes} bytes · ${opened.route.kind} · ${opened.route.effectiveIdentity}`;mountEditor(opened.text,params.line??1,resourcePath,params.column??1,params.length??0)}catch(error){if(alive)status=(error as Error).message}})();
    return()=>{alive=false;disposed=true;unregister();window.removeEventListener('atlas:file-reveal',reveal);window.removeEventListener('atlas:save-buffer-as',saveBuffer);window.removeEventListener('atlas:save-active',saveActive);window.removeEventListener('atlas:save-as-active',saveAsActive);window.removeEventListener('keydown',captureSaveAs,true);window.removeEventListener('keydown',captureFind,true);view?.destroy()}});
</script>
<section class="panel file-panel" bind:this={section}><header><div><strong>{dirty?'● ':''}{resourcePath||atlasBuffers.get(params.bufferId??'')?.name||'File'}</strong><span>{status}</span></div><div class="file-actions"><button onclick={saveAs} disabled={!params.bufferId||saving} title="Save as" aria-label="Save as">Save as</button><button onclick={toggleHistory} disabled={!resourcePath||!fingerprint} aria-expanded={historyOpen} title="Restore previous version" aria-label="Restore previous version"><History size={14}/></button><button onclick={save} disabled={(!dirty&&!params.bufferId)||saving} title="Save file" aria-label="Save file"><Save size={14}/></button></div></header>
  {#if historyOpen}<div class="version-history" role="region" aria-label="Previous versions">
    <div class="version-history-head"><strong>Previous versions</strong><span>Kept on the machine holding this file · restoring is versioned too</span><button onclick={()=>historyOpen=false} aria-label="Close previous versions">×</button></div>
    {#if versionsMessage}<p class="version-note">{versionsMessage}</p>{/if}
    <ol>{#each versions as version (version.slot)}<li class:selected={versionPreview?.slot===version.slot}><span class="version-meta"><b>Version {version.slot}</b><span>{formatTime(version.replacedAt)}</span><span>{formatBytes(version.bytes)}</span></span><span class="version-actions"><button onclick={()=>previewVersion(version.slot)} aria-label={`Preview version ${version.slot}`}>Diff</button><button onclick={()=>restoreVersion(version)} disabled={restoring} aria-label={`Restore version ${version.slot}`}>Restore</button></span></li>{/each}</ol>
    {#if versionPreview}<div class="version-diff" aria-label={`Changes restoring version ${versionPreview.slot} would make`}>{#if versionPreview.message}<p class="version-note">{versionPreview.message}</p>{/if}{#if versionPreview.diff}{#each versionPreview.diff as line}<div class={`diff-${line.kind}`}><i>{line.kind==='add'?'+':line.kind==='remove'?'−':line.kind==='gap'?'':' '}</i><code>{line.text}</code></div>{/each}{/if}</div>{/if}
  </div>{/if}
  <div class="editor" bind:this={host}>{#if !view&&status==='Opening file…'}<LoadingState message="Opening file…"/>{/if}</div></section>
<style>
  .version-history{flex:none;max-height:45%;overflow:auto;border-bottom:1px solid var(--atlas-border);background:var(--atlas-surface-0);font-size:11px}
  .version-history-head{display:flex;align-items:center;gap:8px;padding:6px 10px;position:sticky;top:0;background:var(--atlas-surface-0)}
  .version-history-head span{color:var(--atlas-muted);font-size:10px;flex:1}
  .version-history-head button{border:0;background:transparent;color:var(--atlas-muted);font-size:15px;padding:0 4px}
  .version-history ol{list-style:none;margin:0;padding:0 6px 6px}
  .version-history li{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:4px 6px;border-radius:var(--atlas-radius-sm)}
  .version-history li.selected,.version-history li:hover{background:var(--atlas-hover)}
  .version-meta{display:flex;gap:10px;align-items:baseline;min-width:0}.version-meta span{color:var(--atlas-muted);font-size:10px;white-space:nowrap}
  .version-actions{display:flex;gap:4px}.version-actions button{padding:2px 8px;font-size:10px}
  .version-note{margin:4px 12px 8px;color:var(--atlas-muted)}
  .version-diff{margin:0 8px 8px;border:1px solid var(--atlas-border);border-radius:var(--atlas-radius-sm);font:11px/1.5 ui-monospace,monospace;max-height:220px;overflow:auto}
  .version-diff div{display:flex;white-space:pre}.version-diff i{width:18px;flex:none;text-align:center;font-style:normal;color:var(--atlas-muted)}
  .diff-add{background:#4ade8018}.diff-remove{background:#ff8d8618}.diff-gap{color:var(--atlas-muted)}
</style>
